import sys

def main():
    lines = sys.stdin.read().split('\n')
    q = int(lines[0])
    st = []
    out = []
    for i in range(q):
        parts = lines[1 + i].split()
        if parts[0] == 'push':
            st.append(int(parts[1]))
        elif parts[0] == 'pop':
            out.append(str(st.pop()) if st else 'EMPTY')
        else:
            out.append(str(st[-1]) if st else 'EMPTY')
    print('\n'.join(out))

