top = 0
out = []
for i in range(q):
    p = lines[1 + i].split()
    if p[0] == 'push':
        arr[top] = int(p[1])
        top += 1
    elif p[0] == 'pop':
        if top == 0:
            out.append('EMPTY')
        else:
            top -= 1
            out.append(str(arr[top]))
    else:
        out.append('EMPTY' if top == 0 else str(arr[top - 1]))
